<?php declare(strict_types=1);require __DIR__.'/_bootstrap.php';require_admin();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id)redirect_to('orders.php');if(is_post()){verify_csrf($_POST['csrf']??'');$status=(string)($_POST['status']??'');if(in_array($status,['new','contacted','completed','cancelled'],true)){$pdo->prepare('UPDATE orders SET status=? WHERE id=?')->execute([$status,$id]);flash('success','Order status updated.');}redirect_to('order.php?id='.$id);}$s=$pdo->prepare('SELECT * FROM orders WHERE id=?');$s->execute([$id]);$o=$s->fetch();if(!$o)redirect_to('orders.php');$colors=json_decode((string)$o['colors'],true);$colors=is_array($colors)?$colors:[$o['colors']];$pageTitle='Order '.$o['order_ref'];$active='orders';require __DIR__.'/includes/layout.php';?><div class="panel"><div class="panel-head"><h2>Order details</h2><span class="badge <?=e($o['status'])?>"><?=e($o['status'])?></span></div><div class="detail-grid"><div class="detail-box"><small>Customer</small><b><?=e($o['fullname'])?></b></div><div class="detail-box"><small>Phone</small><b><?=e($o['phone'])?></b></div><div class="detail-box"><small>Location</small><b><?=e($o['location'])?></b></div><div class="detail-box"><small>Fabric</small><b><?=e($o['fabric_type'])?></b></div><div class="detail-box"><small>Colours</small><b><?=e(implode(', ',$colors))?></b></div><div class="detail-box"><small>Measurement</small><b><?=e($o['measurement']==='yard'?'Per yard (36 inches)':'Per trouser length (45 inches)')?></b></div><div class="detail-box"><small>Quantity</small><b><?=e($o['quantity'])?></b></div><div class="detail-box"><small>Price / unit</small><b><?=money($o['unit_price'])?></b></div><div class="detail-box"><small>Subtotal</small><b><?=money($o['subtotal'])?></b></div><div class="detail-box"><small>Anniversary saving</small><b><?=money($o['discount'])?></b></div><div class="detail-box"><small>Total</small><b><?=money($o['total_amount'])?></b></div><div class="detail-box"><small>Date</small><b><?=e($o['created_at'])?></b></div></div><div class="detail-box" style="margin-top:15px"><small>Customer note</small><b><?=nl2br(e($o['description']?:'No additional description.'))?></b></div><form method="post" style="margin-top:18px"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="filterbar"><select name="status"><option value="new" <?=$o['status']==='new'?'selected':''?>>New</option><option value="contacted" <?=$o['status']==='contacted'?'selected':''?>>Contacted</option><option value="completed" <?=$o['status']==='completed'?'selected':''?>>Completed</option><option value="cancelled" <?=$o['status']==='cancelled'?'selected':''?>>Cancelled</option></select><button class="btn btn-gold">Update status</button><a class="btn btn-light" href="tel:<?=e($o['phone'])?>">Call</a><a class="btn btn-light" target="_blank" href="https://wa.me/<?=preg_replace('/\D+/','',$o['phone'])?>">WhatsApp</a><a class="btn btn-light" href="orders.php">Back</a></div></form></div><?php require __DIR__.'/includes/footer.php';?>
